/**
 * @fileoverview GitHub Issue List tool — list issues for a repository.
 */
export class GitHubIssueListTool {
    service;
    name = 'github_issue_list';
    description = 'List issues for a GitHub repository. Supports filtering by state and labels.';
    category = 'developer';
    hasSideEffects = false;
    inputSchema = {
        type: 'object',
        required: ['owner', 'repo'],
        properties: {
            owner: { type: 'string', description: 'Repository owner (user or org)' },
            repo: { type: 'string', description: 'Repository name' },
            state: {
                type: 'string',
                enum: ['open', 'closed', 'all'],
                description: 'Issue state filter (default: open)',
            },
            labels: { type: 'string', description: 'Comma-separated label names to filter by' },
            per_page: { type: 'number', description: 'Results per page (max 30, default 10)' },
        },
    };
    constructor(service) {
        this.service = service;
    }
    async execute(args) {
        try {
            const octokit = this.service.getOctokit();
            const { data } = await octokit.rest.issues.listForRepo({
                owner: args.owner,
                repo: args.repo,
                state: args.state ?? 'open',
                labels: args.labels,
                per_page: Math.min(args.per_page ?? 10, 30),
            });
            return {
                success: true,
                data: data
                    .filter((i) => !i.pull_request) // Exclude PRs (GitHub API returns them too)
                    .map((i) => ({
                    number: i.number,
                    title: i.title,
                    state: i.state,
                    author: i.user?.login,
                    labels: i.labels.map((l) => (typeof l === 'string' ? l : l.name)),
                    comments: i.comments,
                    created_at: i.created_at,
                    url: i.html_url,
                })),
            };
        }
        catch (err) {
            return { success: false, error: err instanceof Error ? err.message : String(err) };
        }
    }
}
